 VALUES ('88d8702c-5c2d-5818-96a3-e209d8a15f02', 2, 'd6689767-a60c-520d-a341-2cbe2d0ab1a2',
         'Document Structure and Semantic HTML', 'بنية المستند و HTML الدلالي', 'HTML',
         'Write a valid HTML5 document skeleton and choose semantic elements over generic containers.', 'أن تكتب هيكل مستند HTML5 صحيحًا وتختار العناصر الدلالية بدل الحاويات العامة.',
         'Every page starts from the same skeleton: <!doctype html>, a <html lang> attribute, <head> with charset and viewport, and a <body>. The <head> holds metadata the browser needs before rendering; the <body> holds what the user sees. Semantic elements — <header>, <nav>, <main>, <article>, <section>, <aside>, <footer> — carry meaning that is free for accessibility and SEO. Use <h1>–<h6> as a real outline rather than for font sizes, which is what CSS is for. Do not reach for <div> when a meaningful element exists: a screen reader user can jump between landmarks only if the landmarks exist.', 'كل صفحة تبدأ من هيكل واحد: ‎<!doctype html>‎ ووسم ‎<html lang>‎، ثم ‎<head>‎ الذي يحوي الترميز وبيانات العرض، و ‎<body>‎ الذي يحوي ما يراه المستخدم. العناصر الدلالية مثل ‎<header>‎ و ‎<nav>‎ و ‎<main>‎ و ‎<article>‎ و ‎<footer>‎ تحمل معنى مجانيًا لإمكانية الوصول وتحسين محركات البحث. استخدم العناوين ‎<h1>‎ حتى ‎<h6>‎ كخريطة حقيقية للصفحة لا للتحكم بحجم الخط، فذلك عمل CSS.', 100,
         'Recreate the structure of a news homepage you know well using only semantic elements. No CSS yet. Validate it.', 'أعد بناء هيكل صفحة إخبارية تعرفها باستخدام العناصر الدلالية فقط، دون أي CSS، ثم تحقّق من صحتها.',
         'A validated, semantic index.html file.', 'ملف index.html دلالي اجتاز التحقق.',
         ARRAY['Your page passes the HTML validator with no errors', 'There is exactly one <h1> and heading levels never skip']::text[], ARRAY['صفحتك تجتاز التحقق دون أخطاء', 'يوجد عنوان رئيسي واحد فقط ولا تقفز في المستويات']::text[],
         'Explain to a friend why <div> everywhere makes a page harder to use with a keyboard and screen reader.', 'اشرح لصديقك لماذا استخدام div في كل مكان يجعل الصفحة أصعب في الاستخدام بلوحة المفاتيح وقارئ الشاشة.',
         ARRAY['1']::text[], 'lesson')
ON CONFLICT (id) DO UPDATE SET
