 VALUES ('1778f5d2-7d19-5220-ab98-5921789dd75e', 5, 'd6689767-a60c-520d-a341-2cbe2d0ab1a2',
         'Tables for Tabular Data', 'الجداول للبيانات الجدولية', 'HTML',
         'Use tables only for tabular data, with proper headers, scope and caption.', 'أن تستخدم الجداول للبيانات الجدولية فقط، مع ترويسات ونطاق ووصف.',
         'A table is for rows and columns of related data, not for page layout — that job belongs to CSS Grid today. Give every table a <caption>, use <th> for header cells, and add scope="col" or scope="row" so assistive tech can associate a cell with its heading. Use <thead>, <tbody> and <tfoot> for structure. For layout purposes, CSS Grid replaces the old table-hack entirely.', 'الجدول للصفوف والأعمدة من البيانات المترابطة، وليس لتخطيط الصفحة؛ فالتخطيط اليوم عمل Grid في CSS. أضف caption لكل جدول، واستخدم th لخلايا الترويسة مع scope لربط كل خلية بترويستها. استخدم thead و tbody و tfoot للبنية. أما التخطيط فاستبدله بـ Grid.', 80,
         'Create a statistics table of at least 6 rows and 4 columns with correct semantics throughout.', 'أنشئ جدول إحصاءات من ستة صفوف وأربعة أعمدة بدلالات صحيحة في كل خلية.',
         'One semantic data table and one Grid-based layout.', 'جدول بيانات دلالي واحد وتخطيط واحد بـ Grid.',
         ARRAY['All header cells use <th> with correct scope', 'No table is used for layout']::text[], ARRAY['كل خلايا الترويسة تستخدم th مع scope صحيح', 'لا يوجد جدول مستخدم للتخطيط']::text[],
         NULL, NULL,
         ARRAY['4']::text[], 'practice')
