 VALUES ('27e15d49-10b5-51a6-88d0-14228cfbcfb0', 17, 'd6689767-a60c-520d-a341-2cbe2d0ab1a2',
         'Positioning: Relative, Absolute, Fixed, Sticky', 'التحديد: نسبي، مطلق، ثابت، لاصق', 'CSS layout',
         'Take elements out of normal flow predictably and understand the containing block.', 'أن تُخرج العناصر من التدفق الطبيعي بعقلانية وتفهم كتلة الاحتواء.',
         'position: relative keeps an element in flow but lets you offset it, and it establishes the containing block for absolutely positioned descendants. absolute removes an element from flow and positions it against the nearest positioned ancestor — which is why "absolute relative to the body" surprises people when they forget a relative parent. fixed positions against the viewport and scrolls with the page; sticky is a hybrid that sticks only within its parent bounds and is the modern tooltip and sticky-header pattern. z-index only works between positioned elements.', 'position: relative يبقي العنصر في التدفق مع إمكانية إزاحته، وهو كتلة الاحتواء للأبناء absolutely positioned. و absolute يخرج العنصر من التدفق ويموضعه مقابل أقرب سلف محدد الموضع. و fixed يواجه نافذة العرض ويمرر معه، و sticky مزيج يلتصق ضمن حدود أبيه وهو النمط الحديث للتلميحات والرؤوس اللاصقة. و z-index يعمل فقط بين العناصر محددة الموضع.', 100,
         'Create a dropdown menu that opens on click, stays above content, and closes on outside click — CSS only where possible.', 'أنشئ قائمة منسدلة تُفتح بالنقر، تبقى فوق المحتوى، وتُغلق بالنقر خارجها — قدر الإمكان بـ CSS فقط.',
         'Four positioning demonstrations with written explanations.', 'أربعة أمثلة تحديد مع شرح مكتوب لكل منها.',
         ARRAY['Every absolute element has an intentional positioned ancestor', 'Overlays appear above all page content']::text[], ARRAY['كل عنصر absolutely له سلف محدد الموضع بقصد', 'الطبقات تظهر فوق كل المحتوى']::text[],
         'Build a sticky sidebar that becomes a normal block on mobile.', 'ابنِ شريطًا جانبيًا لاصقًا يتحول إلى كتلة عادية على الجوال.',
         ARRAY['16']::text[], 'lesson')
ON CONFLICT (id) DO UPDATE SET
