 VALUES ('a4723026-b064-59b8-93cf-7538682d9517', 18, 'd6689767-a60c-520d-a341-2cbe2d0ab1a2',
         'Layout Project: Blog Homepage', 'مشروع التخطيط: صفحة مدوّنة', 'CSS project',
         'Build a complete multi-region page layout combining Grid, Flexbox and positioning.', 'أن تبني تخطيط صفحة متعدد المناطق يجمع Grid و Flexbox والتحديد.',
         'A blog homepage forces every layout skill into one artifact: a sticky header, a featured post, a Grid of cards, a sidebar, and a footer. Use Grid for the page regions and Flexbox inside each region — that division of labour is the real lesson. Test at three widths: 375px, 768px and 1280px. The breakpoint should follow where the content breaks, not round device numbers, but be aware of common widths.', 'صفحة المدوّنة تُجبر كل مهارة تخطيط في ناتج واحد: رأس لاصق، ومقال مميّز، وشبكة بطاقات، وشريط جانبي، وتذييل. استخدم Grid لمناطق الصفحة و Flexbox داخل كل منطقة؛ هذا التقسيم هو الدرس الحقيقي. اختبر ثلاثة عروض: 375px و768px و1280px. نقطة التوقف يجب أن تتبع موضع كسر المحتوى لا أرقام الأجهزة.', 120,
         'Build a blog homepage with at least eight article cards, a featured post and a working sticky header.', 'ابنِ صفحة مدوّنة بثماني بطاقات مقالات على الأقل ومقال مميّز ورأس لاصق يعمل.',
         'A responsive blog homepage with no layout breakage at any width.', 'صفحة مدوّنة متجاوبة دون أي كسر في التخطيط عند أي عرض.',
         ARRAY['No horizontal scrollbar at 320px width', 'Grid handles page regions; Flexbox handles inner layout']::text[], ARRAY['لا شريط تمرير أفقي عند عرض 320px', 'Grid لمناطق الصفحة و Flexbox للتخطيط الداخلي']::text[],
         'Make the sidebar collapse below the content on mobile without duplicating any markup.', 'اجعل الشريط الجانبي ينزل تحت المحتوى على الجوال دون تكرار أي وسوم.',
         ARRAY['17']::text[], 'project')
