 VALUES ('7c84add8-4c90-57bf-8682-699042f094a0', 36, '9d716dbf-bb13-502f-9314-afc610e5ed32',
         'Conditionals and Truthiness', 'الجمل الشرطية وقيم الصدق', 'Control flow',
         'Write clear conditionals and apply a truthiness table without guessing.', 'أن تكتب جملًا شرطية واضحة وتطبّق جدول قيم الصدق دون تخمين.',
         'if/else is the default; a ternary for a single short assignment; switch when comparing one value against several constants. The falsy list is short and worth memorising exactly: false, 0, -0, 0n, "", null, undefined, NaN. Everything else is truthy — including [], {}, "false", "0" and 32n. That surprises people constantly: an empty array and empty object are truthy. Boolean("false") is true. Prefer explicit comparison over relying on truthiness when the value could be 0 or "". Optional chaining (?. ) short-circuits safely through null and undefined chains; optional call (?.) does the same for functions. They do nothing for falsy-but-defined values, which is a feature, not a bug.', '‎if/else‎ هي القاعدة، والشرط الثلاثي لإسناد قصير واحد، و switch عند مقارنة قيمة واحدة بعدة ثوابت. قائمة القيم غير الصحيحة قصيرة وتستحق الحفظ: false و 0 و -0 و 0n و "" و null و undefined و NaN. ما عدا ذلك فهو صحيح، بما في ذلك ‎[]‎ و ‎{}‎ و "false" و "0" و 32n. هذا يفاجئ الناس باستمرار: المصفوفة الفارغة والكائن الفارغ صحيحان منطقيًا. و Boolean("false") تساوي true. فضّل المقارنة الصريحة على الاعتماد على قيم الصدق عندما قد تكون القيمة 0 أو نصًا فارغًا. والسلسلة الاختيارية ‎?.‎ تتوقف بأمان عند null و undefined؛ وهي لا تفعل شيئًا مع القيم غير الصحيحة لكن المعرّفة، وهذه ميزة لا علّة.', 90,
         'Write a form validator that reports every failing field at once, using clear truthiness rules.', 'اكتب دالة تتحقق من نموذج وتبلّغ عن كل حقل فاشل دفعة واحدة، بقواعد صدق واضحة.',
         'A truthiness reference table and a multi-field validator.', 'جدول مرجعي لقيم الصدق ودالة تحقق من عدة حقول.',
         ARRAY['Empty array and empty string are handled intentionally, not by accident', 'The validator reports all errors, not just the first']::text[], ARRAY['المصفوفة والنص الفارغان يُعالَجان بقصد لا صدفة', 'دالة التحقق تُبلّغ عن كل الأخطاء لا أولها فقط']::text[],
         'Write a validation helper that treats an empty array or string as empty, and document why that is a policy decision.', 'اكتب دالة تحقق تعامل المصفوفة أو النص الفارغ كفراغ، ووثّق لماذا قرار سياستي.',
         ARRAY['35']::text[], 'lesson')
