 VALUES ('e6e5949c-7b90-51ed-b57d-b642f9bc6dc1', 94, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'REST API Boilerplate', 'REST API Boilerplate', 'REST API',
         'Build a minimal API with GET, POST, PUT, DELETE routes and in-memory storage.', 'Build a minimal API with GET, POST, PUT, DELETE routes and in-memory storage.',
         'A basic REST API CRUD scaffold. Each route follows app.METHOD(path, handler). Use an in-memory JavaScript object as the "database". Validate the request body with body-parser or Express''s built-in middleware. Return appropriate status codes and JSON shapes for each operation.', 'A basic REST API CRUD scaffold. Each route follows app.METHOD(path, handler). Use an in-memory JavaScript object as the "database". Validate the request body with body-parser or Express''s built-in middleware. Return appropriate status codes and JSON shapes for each operation.', 120,
         'Start the API and test all four routes with curl or Postman.', 'Start the API and test all four routes with curl or Postman.',
         'A functional API with CRUD endpoints and an in-memory store.', 'A functional API with CRUD endpoints and an in-memory store.',
         ARRAY['All four CRUD routes respond with JSON', 'Status codes are appropriate (200, 201, 404, etc.)']::text[], ARRAY['All four CRUD routes respond with JSON', 'Status codes are appropriate (200, 201, 404, etc.)']::text[],
         'Add a PATCH /items/:id route that partially updates an item.', 'Add a PATCH /items/:id route that partially updates an item.',
         ARRAY['93']::text[], 'project')
