 VALUES ('60befe05-5ece-582e-a0aa-003144f86299', 95, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Backend Review and Consolidation', 'Backend Review and Consolidation', 'Review',
         'Re-read the API you built and fix weaknesses: route duplication, missing status codes, unhandled errors.', 'Re-read the API you built and fix weaknesses: route duplication, missing status codes, unhandled errors.',
         'A deliberate review day. Re-read the routes you wrote, look for: routes that overlap, status codes that are missing for edge cases, try-catch blocks that are absent, and any place where the server might crash on bad input. Then run every curl test you can think of.', 'A deliberate review day. Re-read the routes you wrote, look for: routes that overlap, status codes that are missing for edge cases, try-catch blocks that are absent, and any place where the server might crash on bad input. Then run every curl test you can think of.', 70,
         'Take your API and add validation for POST body – reject missing required fields.', 'Take your API and add validation for POST body – reject missing required fields.',
         'A cleaned-up API plus a written list of mistakes fixed.', 'A cleaned-up API plus a written list of mistakes fixed.',
         ARRAY['Every route has a try-catch', '404 responds with JSON error']::text[], ARRAY['Every route has a try-catch', '404 responds with JSON error']::text[],
         'Add a route that gracefully handles a non-existent resource (404 with a JSON error body).', 'Add a route that gracefully handles a non-existent resource (404 with a JSON error body).',
         ARRAY['94']::text[], 'review')
