 VALUES ('019cc50b-c959-5015-98ca-981000fdc1e2', 96, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Async Functions and Promises', 'Write an async function that fetches data from an API and logs the result.', 'Async JavaScript',
         'Write async/await, understand how it wraps Promises, and avoid common pitfalls.', 'Write async/await, understand how it wraps Promises, and avoid common pitfalls.',
         'async marks a function as asynchronous. await pauses execution until the Promise resolves. All await expressions must be inside async functions. Unhandled rejections crash the process — always try/catch around await. Promise.all settles all promises concurrently; Promise.race picks the first that settles.', 'async marks a function as asynchronous. await pauses execution until the Promise resolves. All await expressions must be inside async functions. Unhandled rejections crash the process — always try/catch around await. Promise.all settles all promises concurrently; Promise.race picks the first that settles.', 90,
         'Write an async function that fetches data from an API and logs the result.', 'Write an async function that fetches data from an API and logs the result.',
         'A script with async/await that fetches two URLs and logs both results.', 'A script with async/await that fetches two URLs and logs both results.',
         ARRAY['Function uses async/await syntax', 'try/catch around each await']::text[], ARRAY['Function uses async/await syntax', 'try/catch around each await']::text[],
         'Write a function that awaits three promises sequentially and logs each result.', 'Write a function that awaits three promises sequentially and logs each result.',
         ARRAY['92']::text[], 'lesson')
