 VALUES ('ce9420f4-5015-5e12-a424-262a3e4c8044', 98, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'HTTP Cookies and Sessions', 'Cookies and Sessions', 'Cookies',
         'Set HttpOnly cookies, manage session lifetimes, and prevent common cookie attacks.', 'Set HttpOnly cookies, manage session lifetimes, and prevent common cookie attacks.',
         'Cookies store state in the browser. HttpOnly prevents JavaScript access. Secure ensures cookies are sent only over HTTPS. SameSite mitigates CSRF. Session stores data server-side and identifies the user via a cookie. Short session timeouts reduce risk.', 'Cookies store state in the browser. HttpOnly prevents JavaScript access. Secure ensures cookies are sent only over HTTPS. SameSite mitigates CSRF. Session stores data server-side and identifies the user via a cookie. Short session timeouts reduce risk.', 90,
         'Set a cookie and verify the flags using DevTools.', 'Set a cookie and verify the flags using DevTools.',
         'A server that sets a cookie with all security flags.', 'A server that sets a cookie with all security flags.',
         ARRAY['Cookie has HttpOnly flag', 'Cookie has Secure flag', 'SameSite is set']::text[], ARRAY['Cookie has HttpOnly flag', 'Cookie has Secure flag', 'SameSite is set']::text[],
         'Set a cookie with HttpOnly; confirm it cannot be read from JavaScript.', 'Set a cookie with HttpOnly; confirm it cannot be read from JavaScript.',
         ARRAY['97']::text[], 'lesson')
