 VALUES ('45f0505c-fb9d-50c3-b687-ee9e9d4941a1', 99, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Rate Limiting and Input Validation', 'Rate Limiting and Validation', 'Security',
         'Protect your API from abuse with rate limiting and strict input validation.', 'Protect your API from abuse with rate limiting and strict input validation.',
         'Rate limiting caps how many requests a client can make in a time window. Use a library like express-rate-limit or implement a token bucket. Input validation rejects malformed data early. Never trust client input; validate type, range, and format on the server. Combine with error handling to avoid leaking stack traces.', 'Rate limiting caps how many requests a client can make in a time window. Use a library like express-rate-limit or implement a token bucket. Input validation rejects malformed data early. Never trust client input; validate type, range, and format on the server. Combine with error handling to avoid leaking stack traces.', 100,
         'Add rate limiting and email validation to an existing Express route.', 'Add rate limiting and email validation to an existing Express route.',
         'An Express route that rate-limits and validates its input.', 'An Express route that rate-limits and validates its input.',
         ARRAY['Rate limiting active', 'Invalid email rejected', 'Body size check active']::text[], ARRAY['Rate limiting active', 'Invalid email rejected', 'Body size check active']::text[],
         'Configure rate limiting to block an IP after 10 failed attempts.', 'Configure rate limiting to block an IP after 10 failed attempts.',
         ARRAY['98']::text[], 'practice')
