 VALUES ('92d82082-e1cc-5caf-a712-f3e254814e83', 100, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'User Authentication API', 'Auth API', 'Authentication project',
         'Build a login/register API with JWTs, cookie-based sessions, and rate limiting.', 'Build a login/register API with JWTs, cookie-based sessions, and rate limiting.',
         'Combine everything from the previous days: register a user (hash the password), login (issue a JWT and set a cookie), protect a route with the JWT middleware, and apply rate limiting to the login endpoint. Handle password confirmation and email format validation.', 'Combine everything from the previous days: register a user (hash the password), login (issue a JWT and set a cookie), protect a route with the JWT middleware, and apply rate limiting to the login endpoint. Handle password confirmation and email format validation.', 120,
         'Full auth API: register, login, protected profile endpoint, rate-limited login.', 'Full auth API: register, login, protected profile endpoint, rate-limited login.',
         'An Express API with registration, login, JWT auth, cookies, and rate limiting.', 'An Express API with registration, login, JWT auth, cookies, and rate limiting.',
         ARRAY['Registration validates email and password', 'Login issues JWT + cookie', 'Protected route returns user data', 'Login is rate-limited']::text[], ARRAY['Registration validates email and password', 'Login issues JWT + cookie', 'Protected route returns user data', 'Login is rate-limited']::text[],
         'Add a refresh-token flow using a separate cookie and revocation list.', 'Add a refresh-token flow using a separate cookie and revocation list.',
         ARRAY['97', '99']::text[], 'project')
