 VALUES ('202df883-8e9a-504b-a2ce-2d47e925a199', 101, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Backend Review and Consolidation', 'Backend Review and Consolidation', 'Review',
         'Re-read your auth API and fix: missing try-catch, invalid JWT secrets, insecure cookie settings.', 'Re-read your auth API and fix: missing try-catch, invalid JWT secrets, insecure cookie settings.',
         'A review day. Take your auth API from day 100 and re-examine it. Look for: try-catch blocks missing around async operations, JWT secret being a hard-coded string, cookies missing HttpOnly/Secure/SameSite, any route that writes user data without validation. Fix each issue and run your test suite.', 'يوم مراجعة. خذ api المصادقة من اليوم 100 وأعاده تذكر للبحث عن: try-catch blocks ناقصة حول العمليات.async operations, JWT secret being a hard-coded string, cookies missing HttpOnly/Secure/SameSite, any route that writes user data without validation. Fix each issue and run your test suite.', 70,
         'Take your auth API and apply all security fixes from days 97-100.', 'Take your auth API and apply all security fixes from days 97-100.',
         'A cleaned-up auth API plus a written list of security fixes.', 'A cleaned-up auth API plus a written list of security fixes.',
         ARRAY['Try-catch around all async routes', 'JWT secret from env', 'All cookies have security flags']::text[], ARRAY['Try-catch around all async routes', 'JWT secret from env', 'All cookies have security flags']::text[],
         'Add rotation for your JWT secret without invalidating existing tokens.', 'Add rotation for your JWT secret without invalidating existing tokens.',
         ARRAY['100']::text[], 'review')
