 VALUES ('a18abdd3-3eb0-5fd3-801c-d361abe7407a', 103, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'API Versioning', 'توثيق API', 'API Design',
         'Support multiple API versions concurrently and deprecate old endpoints gracefully.', 'Support multiple API versions concurrently and deprecate old endpoints gracefully.',
         'URL versioning (/v1/resources, /v2/resources) and header versioning (Accept: v2) are two common approaches. Deprecate endpoints with a Link header and a JSON body explaining the migration path. Keep old versions running until all clients have migrated.', 'التمكين من ترقيم versioning URLs (/v1/resources, /v2/resources) أو عبر الرؤوس (Accept: v2) هي نهجان شائعان. retire endpoints برفع Header Link وتقديم جسم JSON يشرح طريق الهجرة. احتفظ بالإصدارات القديمة حتى migrates جميع clients.', 90,
         'Version an existing Express route for v1 and v2, and add deprecation headers.', 'Version an existing Express route for v1 and v2, and add deprecation headers.',
         'An Express route available at both /v1 and /v2 with deprecation headers for v1.', 'An Express route available at both /v1 and /v2 with deprecation headers for v1.',
         ARRAY['v1 and v2 routes both functional', 'Link header present on v1', 'Deprecation message in body']::text[], ARRAY['v1 و v2 routes both functional', 'Link header موجود على v1', 'رسالة deprecation في الجسم']::text[],
         'Add a Link header with deprecation for a v1 endpoint and verify with curl', 'Add a Link header with deprecation for a v1 endpoint and verify with curl',
         ARRAY['91']::text[], 'lesson')
