 VALUES ('6c1b51b0-96a8-5e20-b378-6e1e90a0e7d9', 104, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Integration Testing', 'Tests تكامل', 'Testing',
         'Write integration tests that spin up a real HTTP server and test API endpoints.', 'Write integration tests that spin up a real HTTP server and test API endpoints.',
         'Integration tests start the server and hit real endpoints. Use supertest to make requests. Test happy paths and error cases. Clean up the database after each test. Aim for fast feedback; keep integration tests separate from unit tests.', 'tests التكامل تبدأ التشغيل الخادم وترسل طلبات للمنفذ الحقيقي. استخدم supertest لإرسال طلبات. اختبر الحالات happy paths والأخطاء. أنهِ قاعدة البيانات بعد كل اختبار. احتفظ بالاختبارات التكامل سريعة؛ وفصلها عن الاختبارات الوحدات.', 100,
         'Write an integration test suite for the auth API (register, login, protected route).', 'Write an integration test suite for the auth API (register, login, protected route).',
         'A Vitest test file that covers the auth API endpoints.', 'A Vitest test file that covers the auth API endpoints.',
         ARRAY['supertest installed', 'Test covers register/login/protected', 'Database reset with beforeEach']::text[], ARRAY['supertest已安装', 'Test covers register/login/protected', 'Database reset with beforeEach']::text[],
         'Write an integration test that a deprecated v1 endpoint returns 410 Gone', 'Write an integration test that a deprecated v1 endpoint returns 410 Gone',
         ARRAY['102']::text[], 'practice')
