 VALUES ('8b96beba-7470-5eda-9440-32082287c70d', 105, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Full Authentication System', 'نظام المصادقة الكامل', 'Authentication project',
         'Build a complete auth system: registration, login, JWT cookies, refresh tokens, and rate limiting.', 'Build a complete auth system: registration, login, JWT cookies, refresh tokens, and rate limiting.',
         'Combine all the pieces from previous days: register (hash password, create user), login (issue access JWT in cookie, refresh token in separate httpOnly cookie), protect routes with JWT middleware, refresh token flow, and rate-limited login. Add password reset via email.', 'دمج كل القطع من الأيام السابقة: التسجيل (تجزئة كلمة المرور، إنشاء المستخدم), تسجيل الدخول (إصدار JWT في cookie، توكن التحديث في cookie منفصل httpOnly), حماية routes بواسطة Middleware JWT, تدفق refresh token, وتطبيق تقييد rate limiting على endpoint تسجيل الدخول. إضافة إعادة تعيين كلمة المرور عبر البريد الإلكتروني.', 120,
         'Full auth system: register, login, JWT cookies, refresh tokens, rate limiting, password reset.', 'Full auth system: register, login, JWT cookies, refresh tokens, rate limiting, password reset.',
         'An Express API with complete auth: register, login, JWT cookies, refresh tokens, rate limiting, password reset.', 'An Express API with complete auth: register, login, JWT cookies, refresh tokens, rate limiting, password reset.',
         ARRAY['Register hashes password', 'Login issues JWT + two cookies', 'Protected route verified', 'Rate-limited login', 'Password reset flow']::text[], ARRAY['تجزئة كلمة المرور في التسجيل', 'تسجيل دخولIssues JWT + كوكيز', 'مسار Protected route verified', 'تسجيل دخول rate-limited', 'تدفق إعادة تعيين كلمة المرور']::text[],
         'Add refresh token revocation on logout and verify old tokens are rejected', 'Add refresh token revocation on logout and verify old tokens are rejected',
         ARRAY['101', '103']::text[], 'project')
