 VALUES ('cb2dcfb5-b793-5011-aeea-1e48c54de726', 106, '249f74c7-cc2c-5c23-b6c8-1d896bb97022',
         'Backend Review and Consolidation', 'Backend Review and Consolidation', 'Review',
         'Re-read your full auth system and fix: missing try-catch, invalid JWT secrets, insecure cookie settings, missing rate limiting.', 'Re-read your full auth system and fix: missing try-catch, invalid JWT secrets, insecure cookie settings, missing rate limiting.',
         'A review day. Take your full auth system from day 105 and re-examine it. Look for: try-catch blocks missing around async operations, JWT secret being a hard-coded string, cookies missing HttpOnly/Secure/SameSite, any route that writes user data without validation, rate limiting missing from login. Fix each issue and run your test suite.', 'يوم مراجعة. خذ system المصادقة الكامل من اليوم 105 وأعاده تذكر للبحث عن: try-catch blocks ناقصة حول العمليات.async operations, JWT secret being a hard-coded string, cookies missing HttpOnly/Secure/SameSite, any route that writes user data without validation, rate limiting missing from login. Fix each issue and run your test suite.', 70,
         'Take your auth system and apply all security fixes from days 97-105.', 'Take your auth system and apply all security fixes from days 97-105.',
         'A cleaned-up auth system plus a written list of security fixes.', 'A cleaned-up auth system plus a written list of security fixes.',
         ARRAY['Try-catch around all async routes', 'JWT secret from env', 'All cookies have security flags', 'Rate limiting active']::text[], ARRAY['Try-catch around all async routes', 'JWT secret from env', 'All cookies have security flags', 'Rate limiting active']::text[],
         'Add rotation for your JWT secret without invalidating existing tokens.', 'Add rotation for your JWT secret without invalidating existing tokens.',
         ARRAY['105']::text[], 'review')
