 VALUES ('7a200a14-75c3-5383-9815-763f7cf8263a', 121, 'ef71b849-2224-52fd-8a8a-37520256275e',
         'SQL Fundamentals', 'SQL Fundamentals', 'SQL',
         'Write SELECT, INSERT, UPDATE, DELETE statements with proper syntax.', 'Write SELECT, INSERT, UPDATE, DELETE statements with proper syntax.',
         'SQL is the standard language for relational databases. SELECT retrieves data, INSERT adds new rows, UPDATE modifies existing data, and DELETE removes rows. Master the basic syntax, including FROM, WHERE, GROUP BY, ORDER BY, and JOIN clauses. Understanding these operations is the foundation for all later database work.', 'SQL هي اللغة القياسية لقواعد البيانات العلائقية. SELECT تسترجع البيانات، INSERT يضيف صفوفاً جديدة، UPDATE يعدِّل البيانات الموجودة، وحذف Eliminates rows. Master the basic syntax, including FROM, WHERE, GROUP BY, ORDER BY, and JOIN clauses. Understanding these operations is the foundation for all later database work.', 90,
         'Create a table, insert 3 rows, update one row''s value, then delete one row. Script the whole sequence.', 'Create a table, insert 3 rows, update one row''s value, then delete one row. Script the whole sequence.',
         'A SQL script with SELECT, INSERT, UPDATE, and DELETE statements.', 'A SQL script with SELECT, INSERT, UPDATE, and DELETE statements.',
         ARRAY['Can write a SELECT with WHERE clause', 'Can write an INSERT statement']::text[], ARRAY['Can write a SELECT with WHERE clause', 'Can write an INSERT statement']::text[],
         'Write a query that joins two tables and returns columns from both.', 'Write a query that joins two tables and returns columns from both.',
         '{}'::text[], 'lesson')
