 VALUES ('32d89fc1-4b41-5f70-82b6-4cb9e65f9460', 122, 'ef71b849-2224-52fd-8a8a-37520256275e',
         'Relational Database Design', 'Relational Database Design', 'Database Design',
         'Normalize a table to 3NF, define primary and foreign keys.', 'Normalize a table to 3NF, define primary and foreign keys.',
         'Database design starts with understanding normal forms. First Normal Form (1NF) ensures atomic values. Second Normal Form (2NF) removes partial dependency. Third Normal Form (3NF) removes transitive dependency. Primary keys uniquely identify rows; foreign keys link tables together. A well-designed schema avoids data redundancy and ensures integrity.', 'Database design starts with understanding normal forms. First Normal Form (1NF) ensures atomic values. Second Normal Form (2NF) removes partial dependency. Third Normal Form (3NF) removes transitive dependency. Primary keys uniquely identify rows; foreign keys link tables together. A well-designed schema avoids data redundancy and ensures integrity.', 90,
         'Normalize a given unnormalized schema to 3NF and draw the ER diagram.', 'Normalize a given unnormalized schema to 3NF and draw the ER diagram.',
         'Normalized schema (3NF) and ER diagram.', 'Normalized schema (3NF) and ER diagram.',
         ARRAY['Can define primary and foreign keys', 'Can explain 3NF']::text[], ARRAY['Can define primary and foreign keys', 'Can explain 3NF']::text[],
         'Design a database schema for a library system with books, members, and loans.', 'Design a database schema for a library system with books, members, and loans.',
         ARRAY['121']::text[], 'lesson')
