 VALUES ('b687e494-f691-552a-814e-252fb585c8b1', 126, 'ef71b849-2224-52fd-8a8a-37520256275e',
         'Authentication Patterns', 'Authentication Patterns', 'Authentication',
         'Understand local auth, password hashing, and the difference between auth vs authorization.', 'Understand local auth, password hashing, and the difference between auth vs authorization.',
         'Authentication verifies who someone is; authorization decides what they can do. Local auth uses a username and password stored in the database, typically with bcrypt or argon2 hashing. Never store plain-text passwords. The auth flow: sign-up (hash + store), sign-in (compare hash), sign-out (invalidate session).', 'Authentication verifies who someone is; authorization decides what they can do. Local auth uses a username and password stored in the database, typically with bcrypt or argon2 hashing. Never store plain-text passwords. The auth flow: sign-up (hash + store), sign-in (compare hash), sign-out (invalidate session).', 90,
         'Write a 3-step sign-up flow description with hashing.', 'Write a 3-step sign-up flow description with hashing.',
         'A written description of the auth flow with hashing steps.', 'A written description of the auth flow with hashing steps.',
         ARRAY['Can distinguish auth from authorization', 'Can list auth flow steps']::text[], ARRAY['Can distinguish auth from authorization', 'Can list auth flow steps']::text[],
         'Describe how you would securely implement password reset.', 'Describe how you would securely implement password reset.',
         ARRAY['125']::text[], 'lesson')
