 VALUES ('1a037910-29c3-552a-b866-e9c8771ca1e4', 127, 'ef71b849-2224-52fd-8a8a-37520256275e',
         'Auth Schema and Seed', 'Auth Schema and Seed', 'Auth Project',
         'Create the authentication tables (users, sessions) with a seed script and hash passwords with bcrypt.', 'Create the authentication tables (users, sessions) with a seed script and hash passwords with bcrypt.',
         'The auth schema includes a users table (id, name, email, password_hash, created_at) and a sessions table (id, user_id, token, expires_at). Use bcrypt to hash passwords in the seed script. This schema will be used by the Supabase Auth integration later.', 'The auth schema includes a users table (id, name, email, password_hash, created_at) and a sessions table (id, user_id, token, expires_at). Use bcrypt to hash passwords in the seed script. This schema will be used by the Supabase Auth integration later.', 120,
         'Create the sessions table and run the seed script with bcrypt hashing.', 'Create the sessions table and run the seed script with bcrypt hashing.',
         'Auth schema with users and sessions tables, seeded with hashed passwords.', 'Auth schema with users and sessions tables, seeded with hashed passwords.',
         ARRAY['Users table has password_hash column', 'Sessions table created', 'Seed script uses bcrypt']::text[], ARRAY['Users table has password_hash column', 'Sessions table created', 'Seed script uses bcrypt']::text[],
