 VALUES ('46a5525d-4c8c-5e8d-964b-8a4fa594eb5a', 181, 'b4349f9f-b323-5ca5-bc93-0c4b6c105f8f',
         'Next.js Basics', 'Next.js Basics', 'Next.js',
         'Initialize a Next.js app, understand the file-based routing, and run the dev server.', 'Initialize a Next.js app, understand the file-based routing, and run the dev server.',
         'Next.js is a full-stack framework built on React. It uses file-based routing out of the box: pages in the `pages` directory become routes. `next dev` starts the development server. Features include image optimization, script loading strategies, and built-in CSS support.', 'Next.js هو إطار عمل كامل الجافا سكريبت تم إنشاؤه على React. استخدام توجيه basado en archivos: الصفحات في دليل `pages` تصبح Routes. `next dev` يبدأ خادم التطوير. features تشمل تحسين الصور، استراتيجيات تحميل السكريبت، ودعم CSSbuiltin.', 90,
         'Initialize a Next.js app and create an about page with a link from the home page.', 'Initialize a Next.js app and create an about page with a link from the home page.',
         'A working Next.js app with at least two pages and navigation.', 'A working Next.js app with at least two pages and navigation.',
         ARRAY['Next.js app initialized', 'Page creates without errors']::text[], ARRAY['Next.js app initialized', 'Page creates without errors']::text[],
         'Add a dynamic route segment (e.g., [id]) and fetch data with getStaticProps.', 'Add a dynamic route segment (e.g., [id]) and fetch data with getStaticProps.',
         '{}'::text[], 'lesson')
