 VALUES ('3abef6db-9abc-56bd-b4cc-d81b50b930c2', 183, 'b4349f9f-b323-5ca5-bc93-0c4b6c105f8f',
         'Data Fetching with getStaticProps', 'Data Fetching with getStaticProps', 'Next.js',
         'Fetch data at build time with getStaticProps and render it in a component.', 'Fetch data at build time with getStaticProps and render it in a component.',
         'getStaticProps runs at build time and passes data as props to the page. This enables pre-rendering and SEO benefits. The data can be fetched from an external API, a headless CMS, or a local JSON file. Use the `fallback: false` option to disable ISR.', 'getStaticProps runs at build time and passes data as props to the page. This enables pre-rendering and SEO benefits. The data can be fetched from an external API, a headless CMS, or a local JSON file. Use the `fallback: false` option to disable ISR.', 100,
         'Create a page that fetches data from an API with getStaticProps and renders it.', 'Create a page that fetches data from an API with getStaticProps and renders it.',
         'A page with static data fetching and pre-rendered HTML.', 'A page with static data fetching and pre-rendered HTML.',
         ARRAY['Data is fetched at build time', 'HTML is pre-rendered']::text[], ARRAY['Data is fetched at build time', 'HTML is pre-rendered']::text[],
         'Add ISR (revalidate) to the page so it regenerates after a set time.', 'Add ISR (revalidate) to the page so it regenerates after a set time.',
         ARRAY['182']::text[], 'practice')
