 VALUES ('e67ee0aa-2da8-5440-a8b4-4893687947a9', 212, 'edd646a2-39f1-5b49-a26f-d758625ac36b',
         'Testing Fundamentals with Vitest', 'Fundamentals Testing with Vitest', 'Testing',
         'Write Vitest tests, use describe, it, expect, and handle async tests.', 'Write Vitest tests, use describe, it, expect, and handle async tests.',
         'Vitest is a fast test runner that works seamlessly with Vite. Use describe to group tests, it to define a test case, and expect to make assertions. async/await tests are supported with the built-in timeout feature.', 'Vitest هو من-runner اختبار سريع يعمل بشكل seamless مع Vite. استخدم describe لتجميع الاختبارات، it لتحديد حالة اختبار، و expect لإجراء المطالبات. تدعم اختبارات async/await مع ميزة timeout المدمجة.', 90,
         'Write a Vitest test suite for a function that adds two numbers, including positive and negative cases.', 'Write a Vitest test suite for a function that adds two numbers, including positive and negative cases.',
         'A Vitest test file with at least three test cases.', 'A Vitest test file with at least three test cases.',
         ARRAY['Can write a test with describe/it/expect', 'Can write an async test']::text[], ARRAY['Can write a test with describe/it/expect', 'Can write an async test']::text[],
         'Write a test that uses beforeEach and afterEach hooks.', 'Write a test that uses beforeEach and afterEach hooks.',
         ARRAY['211']::text[], 'lesson')
