 VALUES ('b644823c-1297-5f29-81da-123fa207ff8e', 214, 'edd646a2-39f1-5b49-a26f-d758625ac36b',
         'Type-Safe Form Validation', 'Form Validation Type-Safe', 'TypeScript project',
         'Build a form with Zod schema validation, TypeScript types, and runtime safety.', 'Build a form with Zod schema validation, TypeScript types, and runtime safety.',
         'Zod is a Type-first schema declaration and validation library. Define a schema for your form fields, and Zod will both validate data at runtime and generate TypeScript types. This ensures that the data your app receives is perfectly shaped, and you never have to manually parse or validate types.', 'Zod هي مكتبة تأكيد والنمط-first schema declaration. عرف.schema لحقول نموذجك، وسيؤكد Zod التأكيد في وقت التشغيل وينتج أنواع TypeScript. هذا يضمن أن البيانات التي receives app are perfectly shaped, and you never have to manually parse or validate types.', 120,
         'Create a registration form with Zod that validates email format, password strength, and matches confirmation.', 'Create a registration form with Zod that validates email format, password strength, and matches confirmation.',
         'A form component with Zod validation and TypeScript types.', 'A form component with Zod validation and TypeScript types.',
         ARRAY['Zod schema validates runtime', 'TypeScript types generated', 'Component displays errors']::text[], ARRAY['Zod schema validates runtime', 'TypeScript types generated', 'Component displays errors']::text[],
         'Add a schema that validates a date is not in the past.', 'Add a schema that validates a date is not in the past.',
         ARRAY['212', '213']::text[], 'project')
ON CONFLICT (id) DO UPDATE SET
   title_en = EXCLUDED.title_en, title_ar = EXCLUDED.title_ar, topic = EXCLUDED.topic,
   objective_en = EXCLUDED.objective_en, objective_ar = EXCLUDED.objective_ar,
   lesson_en = EXCLUDED.lesson_en, lesson_ar = EXCLUDED.lesson_ar,
   estimated_minutes = EXCLUDED.estimated_minutes,
   exercise_en = EXCLUDED.exercise_en, exercise_ar = EXCLUDED.exercise_ar,
