 VALUES ('44319f78-935e-52c4-a749-e31c1958d979', 215, 'edd646a2-39f1-5b49-a26f-d758625ac36b',
         'TypeScript & Testing Review', 'Review TypeScript and Testing', 'Review',
         'Refactor your form validation to use type-safe patterns, and write a test suite for the validator.', 'Refactor your form validation to use type-safe patterns, and write a test suite for the validator.',
         'A review day. Take your form validation code and refactor it to use Zod for schema-based validation and TypeScript for type safety. Then write a Vitest test suite that covers the validator''s edge cases.', 'يوم مراجعة. مراجعة كود تأكيد صحة النموذج واستخدام Zod للتأكيد، ثم اكتب مجموعة اختبارات Vitest تغطي الحالات الحدية.', 70,
         'Refactor your form validation and write test cases for edge cases like invalid email format and mismatched passwords.', 'Refactor your form validation and write test cases for edge cases like invalid email format and mismatched passwords.',
         'A refactored form with Zod and a passing Vitest test suite.', 'A refactored form with Zod and a passing Vitest test suite.',
         ARRAY['Form uses Zod validation', 'Vitest suite runs without errors', 'Edge cases covered']::text[], ARRAY['Form uses Zod validation', 'Vitest suite runs without errors', 'Edge cases covered']::text[],
         'Add a schema that validates a password must contain at least one number and one special character.', 'Add a schema that validates a password must contain at least one number and one special character.',
         ARRAY['214']::text[], 'review')
ON CONFLICT (id) DO UPDATE SET
   title_en = EXCLUDED.title_en, title_ar = EXCLUDED.title_ar, topic = EXCLUDED.topic,
